#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int INF = 1e9;
    int dp[3] = {0, INF, INF};

    for (int i = 0; i < n; ++i) {
        int activity;
        cin >> activity;

        int next[3] = {
            min({dp[0], dp[1], dp[2]}) + 1,
            INF,
            INF
        };

        if (activity & 1)
            next[1] = min(dp[0], dp[2]);

        if (activity & 2)
            next[2] = min(dp[0], dp[1]);

        for (int j = 0; j < 3; ++j)
            dp[j] = next[j];
    }

    cout << min({dp[0], dp[1], dp[2]}) << '\n';
    return 0;
}

